import {AIFeatures} from '../../src/features/ai.ts';import type {Draft,Experiment,RecordData} from '../../src/domain/types.ts';
import catalog from '../../src/data/catalog.json';import {OCRReviewEditor} from '../../src/features/ocr-review.ts';import {reviewOCR} from '../../src/domain/ocr.ts';import {fields} from '../../src/domain/model.ts';
export function verifyCatalogEditors(){const host=document.createElement('div');document.body.append(host);let checked=0,maximum=0;try{for(const exp of catalog.experiments as Experiment[]){const data:Record<string,unknown>={};for(const f of fields(exp.schema))if(f.type==='array')data[f.key]=Array.from({length:f.variableLength?f.minLength??3:f.length??3},(_,i)=>i);for(const f of fields(exp.schema))if(f.type==='matrix')data[f.key]=Array.from({length:f.rows??0},()=>Array.from({length:f.colsFrom?(data[f.colsFrom] as unknown[]).length:f.cols??0},(_,i)=>i));else if(f.type!=='array')data[f.key]=f.type==='science'?2.7e-9:1;const review=reviewOCR(exp.schema,JSON.stringify({data})),editor=new OCRReviewEditor(exp.schema,review,()=>{});editor.mount(host);if(JSON.stringify(editor.corrected().values)!==JSON.stringify(review.values))throw Error(exp.name+'校对字段往返不一致');maximum=Math.max(maximum,host.querySelectorAll('[data-ocr-edit]').length);editor.leave();checked++;}return {checked,maximum};}finally{host.remove();}}
export async function createOCRCorrectionFixture(){const exp={id:'abcdef123456',sourceId:'测试',name:'识图校对测试',category:'mechanics',schema:{groups:[{name:'测量',fields:[{key:'x',label:'位置',unit:'mm',type:'array',variableLength:true,minLength:3,maxLength:5,required:true},{key:'y',label:'两组读数',unit:'cm',type:'matrix',rows:2,colsFrom:'x',rowLabels:['左侧','右侧'],required:true},{key:'k',label:'常数',type:'science',unit:'A/mm',required:true}]}]}} as Experiment;let doc:RecordData={version:1,experimentId:exp.id,date:'2026-10-25',updatedAt:new Date().toISOString(),draft:{x:['','',''],y:[['','',''],['','','']],k:{mantissa:'',exponent:''}}},calls=0,applies=0,fail=false,pending=false,late:(()=>void)|undefined;const image='data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a5ioAAAAASUVORK5CYII=';const context=()=>({exp,doc,photo:{path:'fixed-photo.png',mime:'image/png',bytes:68,width:1,height:1,sha256:'a'.repeat(64)},imageUrl:image,blocked:false});
 const view=new AIFeatures({context,apply:async(_context,draft:Draft)=>{applies++;if(pending)await new Promise<void>(r=>late=r);if(fail)throw Error('模拟录入保存失败');doc={...doc,draft};},notice:()=>{}},{status:async()=>({hasKey:true}),complete:async()=>{calls++;return {text:JSON.stringify({data:{x:[0,1,2],y:[[1,2,3],[4,5,6]],k:2.7e-9},warnings:{k:'指数待核对'}}),elapsedMs:10};}});await view.ocr();return {state:()=>({calls,applies,open:view.isOpen,saving:view.isSaving}),draft:()=>doc.draft,reopen:()=>view.ocr(),close:()=>view.close(),fail:(v:boolean)=>fail=v,change:()=>{doc={...doc,draft:{...doc.draft,x:['9','8','7']}};},clear:()=>{doc={...doc,draft:{x:['','',''],y:[['','',''],['','','']],k:{mantissa:'',exponent:''}}};},pending:()=>pending=true,late:()=>{pending=false;late?.();}};
}
